DO $$ DECLARE old_definition text; BEGIN SELECT pg_get_constraintdef(oid) INTO old_definition FROM pg_constraint WHERE conrelid='public.store_products'::regclass AND conname='store_products_subcategoria_valid'; IF old_definition IS NULL THEN RAISE EXCEPTION 'Existing subcategory validation not found'; END IF; ALTER TABLE public.store_products DROP CONSTRAINT store_products_subcategoria_valid; EXECUTE 'ALTER TABLE public.store_products ADD CONSTRAINT store_products_subcategoria_valid CHECK ((' || substring(old_definition from 8 for length(old_definition)-8) || ') OR subcategoria IN (''Comida seca para perros'',''Comida húmeda para perros'',''Premios para perros'',''Accesorios (pads)'',''Comida seca para gatos'',''Comida húmeda para gatos'',''Premios para gatos'',''Arena para gatos y accesorios''))'; END $$;